var TURNING_POINTS=[{"id":"tp-vector-rescue","eventIds":["wet-vector-rescue"],"stream":"wetlab","substream":null,"title":"Mammalian expression vector rescue","before":"First synthesised constructs arrived in a high-copy cloning backbone that could be propagated in E. coli.","evidence":"Backbone annotation showed ColE1, β-lactamase and sequencing adapters — but no mammalian promoter and no polyadenylation signal, so the inserts could never be transcribed in HEK293.","decision":"Consolidate all constructs onto pcDNA3.1(+), supplying CMV promoter, BGH poly(A) and NeoR for G418 selection.","after":"Subsequent construct work proceeded on a host-appropriate mammalian expression backbone rather than attempting a one-off PCR rescue into a linear cassette."},{"id":"tp-orco-reporter-redesign","eventIds":["wet-fusion-redesign"],"stream":"wetlab","substream":null,"title":"Orco reporter redesign after weak VUAA1 signal","before":"First-generation reporting module used a bicistronic Orco → IRES → GCaMP6 architecture.","evidence":"VUAA1 challenge produced a real but very weak green fluorescence increase — visible on careful inspection, too small to record reliably or quantify. Assay metadata and traces remain incomplete in the source.","decision":"Redesign the reporter as a single ORF translational fusion: GCaMP6f–(GGGGS)₃–DmOrco (N-terminal sensor), with in-silico verification before resynthesis.","after":""},{"id":"tp-v1-do-not-fabricate","eventIds":["hw-v1-drc-review"],"stream":"drylab","substream":"hardware","title":"Do not fabricate PCB V1","before":"A complete four-layer V1 layout integrated the optical driver, analog front end, ADC/reference, ESP32, regulators and Raspberry Pi interface.","evidence":"Pre-manufacturing ERC/DRC evaluation returned 73 DRC violations, 4 unconnected items, 7 ERC errors and 11 ERC warnings. The archive is design-rule evaluation, not a full circuit simulation.","decision":"Do not fabricate V1. Treat the findings as the first engineering test and obtain professional review.","after":"Hardware work shifted from fabrication toward correction lists, external review packaging and a V2 redesign path."},{"id":"tp-professional-review","eventIds":["hw-professional-review-cycle-1"],"stream":"drylab","substream":"hardware","title":"Professional review resets design priorities","before":"V1 was prepared as a package for external schematic/layout review (including high-impedance TIA/guard and manufacturability scope).","evidence":"Professional review and internal re-evaluation flagged LMP7721 pin mapping, guard routing, photodiode pad interpretation, TIA feedback placement, ADC networks, precision-reference circuitry and ESP32 EN/BOOT behavior.","decision":"Produce a V2 correction list and revise requirements around the whole weak-light signal path — not ADC resolution or TIA gain alone.","after":"Design attention centered on leakage, noise, parasitics and calibration as first-class constraints for the next layout."},{"id":"tp-remove-raspberry-pi","eventIds":["hw-v2-simplification"],"stream":"drylab","substream":"hardware","title":"Remove Raspberry Pi from the standalone reader","before":"V1 integrated a Raspberry Pi interface alongside ESP32 control.","evidence":"ESP32 already provides low-level acquisition, digital processing and wireless communication; heavier computational analysis can run externally.","decision":"Reduce hardware complexity: remove the Raspberry Pi and move toward ESP32-standalone operation with battery power, USB-C charging and local power-path control.","after":""},{"id":"tp-snn-hyperparameter-breakthrough","eventIds":["dry-snn-baseline","dry-snn-hyperparameter-breakthrough"],"stream":"drylab","substream":"model","title":"SNN readout is tunable, not fundamentally capped","before":"July fly-SNN sweeps on a pooled split reached only ~0.545 best single-run F1 with unstable, non-monotonic learning curves, suggesting a stuck MBON readout.","evidence":"August cleaning reduced exposures 9726→8421; raising PN→KC sparsity 0.05→0.2 and loosening lateral inhibition 2000→500 pushed F1 to 0.800 under pca-3, overturning the earlier “fundamentally capped” reading. A documented baseline setting later reached F1 0.868 (single-split/seed limitations remain).","decision":"Treat the bottleneck as hyperparameter and representation/preprocessing work rather than an inherent ceiling; continue cleanup and more rigorous validation.","after":""}];
